        isTrue,
        reason: 'the root library lockfile stays uncommitted.',
      );
      expect(
        gitIgnored('packages/fa_ui/pubspec.lock', root),
        isTrue,
        reason: 'library packages under packages/ keep ignoring their '
            'lockfiles.',
